class TestNodeLifecycle:
    def test_start_transitions_to_active(self, node):
        n, mock_sm, _ = node
        n.start()
        mock_sm.transition_to.assert_called_once_with("ACTIVE")

    def test_stop_transitions_to_terminated(self, node):
        n, mock_sm, _ = node
        n.stop()
        mock_sm.transition_to.assert_called_once_with("TERMINATED")

    def test_suspend_transitions_to_suspended(self, node):
        n, mock_sm, _ = node
        n.suspend()
        mock_sm.transition_to.assert_called_once_with("SUSPENDED")

    def test_resume_transitions_to_active(self, node):
        n, mock_sm, _ = node
        n.resume()
        mock_sm.transition_to.assert_called_once_with("ACTIVE")

class TestNodeMessaging:
    def test_send_message_uses_crypto_signing(self, node):
        n, _, mock_crypto = node
        n.send_message("peer_1", {"data": "test"})
        mock_crypto.sign.assert_called_once()

    def test_send_message_returns_message_id(self, node):
        n, _, _ = node
        msg_id = n.send_message("peer_1", {"data": "test"})
        assert isinstance(msg_id, int)
        assert msg_id > 0

    def test_receive_message_validates_signature(self, node):
        n, _, mock_crypto = node
        mock_crypto.verify.return_value = True
        result = n.receive_message("peer_1", {"data": "test"}, "signature")
        assert result is True

    def test_receive_message_rejects_invalid_signature(self, node):
        n, _, mock_crypto = node
        mock_crypto.verify.return_value = False
        with pytest.raises(PermissionError):
            n.receive_message("peer_1", {"data": "test"}, "bad_signature")

